test('invalid options raise INVALID_OPTIONS', () => {
  const snapshot = new Workspace().exportJSON();
  const cases = [
    undefined,
    null,
    [],
    {},
    { mode: 'upsert' },
    { mode: 'merge', dryRun: 'yes' },
    { mode: 'merge', dryRun: null },
    { mode: 'merge', dryRun: 0 },
